export function minimumSpanningTreeCost(n, edges) {
  if (n <= 1) return 0;
  const parent = Array.from({ length: n }, (_, vertex) => vertex);
  const sizes = Array(n).fill(1);
  function find(vertex) {
    while (parent[vertex] !== vertex) {
      parent[vertex] = parent[parent[vertex]];
      vertex = parent[vertex];
    }
    return vertex;
  }
  let total = 0;
  let used = 0;
  for (const [from, to, weight] of [...edges].sort((a, b) => a[2] - b[2])) {
    let left = find(from);
    let right = find(to);
    if (left === right) continue;
    if (sizes[left] < sizes[right]) [left, right] = [right, left];
    parent[right] = left;
    sizes[left] += sizes[right];
    total += weight;
    used++;
  }
  return used === n - 1 ? total : -1;
}

